test_that("validate_outliers finds artificial errors", {
  v <- prep_visits(nedap, verbose = 0)
  res <- validate_outliers(v, methods = list(rlm = "rlm", sd = "sd", track = "track"), rate = 0.05,
                           size = c(10, 20), reps = 1, verbose = 0)
  expect_s3_class(res, "ppt_validation")
  expect_equal(res$summary$method, c("none", "rlm", "sd", "track"))
  expect_true(outlier_qc(qc_config(), "track")$weight_track)
  expect_false(outlier_qc(qc_config(), "rlm")$weight_track)
  expect_equal(outlier_qc(qc_config(), c("track", "sd"))$weight_outlier, "sd")
  s <- res$summary
  expect_lt(s[method == "none", sensitivity], 0.1)   # weight_range only
  expect_gt(s[method == "rlm", sensitivity], 0.8)
  expect_lt(s[method == "rlm", false_positive_rate], 0.1)
  expect_true(all(abs(s$adg_bias) < 20))
  # reproducible
  again <- validate_outliers(v, methods = list(rlm = "rlm", sd = "sd", track = "track"), rate = 0.05,
                             size = c(10, 20), reps = 1, verbose = 0)
  expect_equal(again$summary, res$summary, check.attributes = FALSE)
  down <- validate_outliers(v, methods = list(rlm = "rlm"), direction = "down",
                            reps = 1, verbose = 0)
  expect_gt(down$summary[method == "rlm", sensitivity], 0.5)
  expect_error(validate_outliers(v, methods = list("rlm")), "named list")
  expect_error(validate_outliers(v, methods = list(x = "nope")), "weight_outlier")
  # the consensus reference has fewer clean records than the qc reference
  qref <- validate_outliers(v, methods = list(rlm = "rlm", stl = "stl"), reps = 1, verbose = 0,
                            reference = "qc")
  cons <- validate_outliers(v, methods = list(rlm = "rlm", stl = "stl"), reps = 1, verbose = 0)
  expect_lt(cons$settings$n_clean, qref$settings$n_clean)
  expect_equal(cons$settings$reference, "consensus")
  expect_error(validate_outliers(v, reference = "x"), "arg")
})

test_that("validate_adg compares curve models", {
  w <- clean_weight(prep_visits(nedap, verbose = 0), verbose = 0)
  res <- validate_adg(w, models = c("poly1", "poly2"), extrap = "curve", trim_days = 10, verbose = 0)
  expect_equal(res$summary$model, c("poly1", "poly2"))
  expect_equal(res$settings$block_days, 7)
  expect_true(all(c("cv_rmse", "cv_mae", "cv_share_over", "bias_late10", "rmse_early10",
                    "spearman_late10", "n_early10") %in% names(res$summary)))
  expect_true(all(res$summary$cv_rmse > 0 & res$summary$cv_rmse < 5))
  # median over pigs; share of pigs above cv_limit
  expect_equal(res$summary$cv_rmse, res$cv[, stats::median(rmse, na.rm = TRUE), by = model]$V1)
  expect_equal(res$summary$cv_share_over, res$cv[, mean(rmse > 10, na.rm = TRUE), by = model]$V1)
  expect_error(validate_adg(w, cv_limit = 0), "cv_limit")
  expect_equal(nrow(res$cv), 2L * w$per_pig[status != "removed", .N])
  # same folds whatever the number of cores
  skip_on_os("windows")
  two <- validate_adg(w, models = c("poly1", "poly2"), extrap = "curve", trim_days = 10, verbose = 0, cores = 2)
  expect_equal(two$summary, res$summary, check.attributes = FALSE)
  expect_error(validate_adg(w, models = "nope"), "curve_model")
  expect_error(validate_adg(w, block_days = 0), "block_days")
})

test_that("validation phases show numbered steps and a results table", {
  withr::local_options(tidypptsda.verbose = 1L)
  out <- cli::ansi_strip(cli::cli_fmt({
    ph <- ppt_phases(2L)
    x <- ph$run("Squares", 3L, function(i) i^2, unit = "item")
    y <- ph$do("Sum", function() sum(unlist(x)))
    ph$finish()
  }))
  expect_true(any(grepl("[1/2] Squares (3 items)", out, fixed = TRUE)))
  expect_true(any(grepl("[2/2] Sum", out, fixed = TRUE)))
  expect_true(any(grepl("^. Done in", out)))
  tab <- cli::ansi_strip(cli::cli_fmt(ppt_result_table(
    "t", c("none", "a", "b"), list(err = c(0, 2, 1), bias = c(0, -1, 3), found = c(0.1, 0.9, 0.5)),
    higher = "found", zero = "bias", pct = "found", exclude = "none")))
  expect_match(tab[grepl("^  b", tab)], "1\\.0\\*")        # lowest error, none excluded
  expect_match(tab[grepl("^  a", tab)], "-1\\.0\\*")       # bias closest to 0
  expect_match(tab[grepl("^  a", tab)], "90\\.0%\\*")      # highest share found
  expect_false(grepl("\\*", tab[grepl("^  none", tab)]))
  # silent with verbose = 0
  w <- clean_weight(prep_visits(nedap, verbose = 0), verbose = 0)
  expect_length(cli::cli_fmt(validate_adg(w, models = "poly2", trim_days = 10, max_pigs = 4, verbose = 0)), 0L)
})

test_that("a parallel worker that dies is reported and its items fail", {
  skip_on_os("windows")
  withr::local_options(tidypptsda.verbose = 0L)
  f <- function(x) {
    if (x == 3) tools::pskill(Sys.getpid(), tools::SIGKILL)
    x
  }
  msg <- cli::cli_fmt(r <- run_with_progress(as.list(1:6), f, cores = 2))
  expect_true(any(grepl("stopped without a result", msg)))
  failed <- vapply(r, function(z) is.list(z) && inherits(z$res, "error"), logical(1))
  expect_equal(failed, rep(c(TRUE, FALSE), 3))
})

test_that("validators clean the remaining records again", {
  w <- clean_weight(prep_visits(nedap, verbose = 0), verbose = 0)
  pig <- w$per_pig[status != "removed", responder][1]
  raw <- raw_weight_records(w, pig)
  # all records again: the same valid records as clean_weight() on all pigs
  again <- reclean_records(raw, w$settings)
  expect_equal(again$entry_time, w$records[responder == pig & outlier == FALSE, entry_time])
  # several pigs in one call, one pig with no record left
  two <- reclean_records(raw_weight_records(w, w$per_pig$responder[1:2]), w$settings)
  expect_setequal(unique(two$responder), w$per_pig$responder[1:2])
  expect_equal(nrow(reclean_records(raw[0], w$settings)), 0L)
  # blocked folds: consecutive days share a fold
  set.seed(1)
  f <- block_folds(as.Date("2024-01-01") + 0:27, k = 2, block_days = 7)
  expect_equal(f, rep(f[c(1, 8, 15, 22)], each = 7))
  expect_setequal(f, 1:2)
  # per-pig data only on the first row
  x <- first_row_info(c("a", "a", "b"), list(a = 1, b = 2))
  expect_equal(x, list(1, NULL, 2))
  # single days give a lower (more optimistic) cross-validation error
  one <- validate_adg(w, models = "poly2", trim_days = 10, max_pigs = 8, block_days = 1, verbose = 0)
  seven <- validate_adg(w, models = "poly2", trim_days = 10, max_pigs = 8, verbose = 0)
  expect_lt(one$summary$cv_rmse, seven$summary$cv_rmse)
})

test_that("validate_weight_fill compares weight fill methods", {
  w <- clean_weight(prep_visits(nedap, verbose = 0), verbose = 0)
  res <- validate_weight_fill(w, methods = c("linear", "poly2"), extrap = "curve",
                              scenarios = c("random30", "blocks3", "late20"), reps = 1, verbose = 0)
  s <- res$summary
  expect_equal(nrow(s), 6L)
  expect_true(all(c("daily_rmse", "daily_mae", "adg_bias", "adg_rmse", "adg_spearman") %in% names(s)))
  expect_true(all(s$daily_rmse > 0 & s$daily_rmse < 10))
  # linear interpolation is close to the recorded weight for random gaps
  expect_lt(s[scenario == "random30" & method == "linear", daily_rmse], 2)
  expect_true(all(is.finite(s$adg_rmse)))
  expect_error(validate_weight_fill(w, methods = "loess"), "methods")
  expect_error(validate_weight_fill(list()), "clean_weight")
})

test_that("validate_adfi measures imputation error", {
  v <- prep_visits(nedap, verbose = 0)
  a <- calc_adg(clean_weight(v, verbose = 0), verbose = 0)
  w <- clean_weight(v, verbose = 0)
  f <- calc_adfi(v, a, verbose = 0)
  res <- validate_adfi(f, w, scenarios = c("random30", "late20", "blocks3", "early10"),
                       reps = 2, verbose = 0)
  expect_true(res$settings$weight)
  s <- res$summary
  expect_equal(nrow(s), 12L)
  expect_true(all(s$n_pigs >= 3L))
  expect_true(all(s$mean_abs_error_pct < 15))
  # random gaps cost less than a long gap at the start
  expect_lt(s[scenario == "random30" & method == "loess_lm", p95_abs_error_pct],
            s[scenario == "late20" & method == "loess_lm", p95_abs_error_pct])
  expect_setequal(unique(s$method), c("loess_pop", "loess_lm", "linear"))
  expect_error(validate_adfi(f, w, scenarios = "rand"), "scenario")
  expect_error(validate_adfi(f, w, min_coverage = 1.01), "coverage")
  expect_error(validate_adfi(f, weight = list()), "clean_weight")
  # without weight: the old behaviour, with a warning
  expect_warning(old <- validate_adfi(f, scenarios = "late20", reps = 1, verbose = 0), "weight")
  expect_false(old$settings$weight)
  # every pig keeps a body weight under every mask
  expect_true(all(s$n_pigs == s$n_pigs[1]))
})

